import importlib.util, pathlib, runpy, sys
original = importlib.util.spec_from_file_location
owner_path = pathlib.Path(sys.argv[1]).resolve()
def trap(name, location, *args, **kwargs):
    if pathlib.Path(location).resolve() == owner_path:
        raise AssertionError('OWNER_IMPORT_ATTEMPTED')
    return original(name, location, *args, **kwargs)
importlib.util.spec_from_file_location = trap
sys.argv = sys.argv[2:]
runpy.run_path(sys.argv[0], run_name='__main__')
